insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a pilot study.','The writer points out a difference between being popular now and being dependable over time.','The writer discusses reliability without mentioning popularity.','The writer argues that long-term reliability is impossible.','The writer says popularity and reliability are exactly the same.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although school uniforms was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in a professional workshop.','Early criticism proved that school uniforms had no value at all.','Later evidence suggested that school uniforms, despite early criticism, may have value if used carefully.','Later evidence showed that school uniforms should never be applied.','The usefulness of school uniforms was accepted before anyone criticized it.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that community gardens solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a policy review.','The report discusses many solutions but never mentions a specific problem.','The report argues that community gardens solves all problems completely.','According to the report, community gardens is not a complete solution but may help with a particular problem.','The report rejects the idea that community gardens can help in any way.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in small communities, as described in a classroom discussion.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a research summary.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent under careful supervision, as described in a public debate.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research after initial trials, as described in a training program.','Future research became unnecessary after the experiment.','The experiment was too large to raise useful questions.','Despite its limited size, the experiment produced results that future studies should examine.','The results were ignored because the experiment was not small.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_9", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
