insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in a public debate.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in schools, as described in a training program.','The process became less transparent after the new system was adopted.','The new system was adopted mainly because it reduced costs.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research for adult learners, as described in an evaluation report.','The experiment was too large to raise useful questions.','The results were ignored because the experiment was not small.','Future research became unnecessary after the experiment.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in public institutions, as described in a committee meeting.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage argues that inconvenient services attract the most users.','The passage says convenience always guarantees satisfaction.','The passage denies that convenience affects service use.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed during periods of change, as described in a student guide.','The plan was accepted although no risks were identified.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in small communities, as described in a pilot study.','Managers ignored the decline because it was caused by one change.','The decline in complaints was sudden and easy to explain.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','Managers blamed a single change because complaints rose quickly.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_10", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
