insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a policy review in a evening language center context.','Managers blamed a single change because complaints rose quickly.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in a classroom discussion in a summer language center context.','The writer argues that long-term reliability is impossible.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although community gardens was initially criticized, later evidence showed that it could be useful when applied carefully in small communities, as described in a research summary.','Later evidence suggested that community gardens, despite early criticism, may have value if used carefully.','The usefulness of community gardens was accepted before anyone criticized it.','Later evidence showed that community gardens should never be applied.','Early criticism proved that community gardens had no value at all.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that health warnings solves every problem; it argues only that it can reduce one specific difficulty when resources are limited, as described in a public debate.','The report discusses many solutions but never mentions a specific problem.','According to the report, health warnings is not a complete solution but may help with a particular problem.','The report argues that health warnings solves all problems completely.','The report rejects the idea that health warnings can help in any way.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion under careful supervision, as described in a training program.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The available data forced the researchers to reject all conclusions.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in an evaluation report.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in schools, as described in a committee meeting.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','The new system was adopted mainly because it reduced costs.','The process became less transparent after the new system was adopted.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
